script:
frappe.after_ajax(() => {
    renderSystemSubscriptions();
});

function renderSystemSubscriptions() {
    frappe.call({
        method: "service_warehouse.service_warehouse.dashboard_chart_source.service_packets.get_total_subscribed_packets_for_host",
        args: {},
        callback: function (response) {
            const tenants = response.message || {};
            console.log("system subscriptions:", tenants);

            const container = root_element.querySelector("#system-subs-list");
            if (!container) return;

            container.innerHTML = "";

            if (Object.keys(tenants).length === 0) {
                container.innerHTML = `<div class="ss-empty">No subscriptions found</div>`;
                return;
            }

            Object.entries(tenants).forEach(([servicePacket, list]) => {

                // ✅ Build packet URL here
                const packetUrl = `/app/service-packet/${encodeURIComponent(servicePacket)}`;

                const tenantDiv = document.createElement("div");
                tenantDiv.className = "ss-tenant";

                tenantDiv.innerHTML = `
                    <div class="ss-tenant-header">
                        <div class="ss-tenant-title">
                            <span class="ss-tenant-dot"></span>
                            <a href="${packetUrl}" class="ss-link">${servicePacket}</a>
                        </div>
                        <div class="ss-count">${list.length} subscriptions</div>
                    </div>
                    <div class="ss-grid"></div>
                `;

                const grid = tenantDiv.querySelector(".ss-grid");

                list.forEach((row) => {
                    const div = document.createElement("div");
                    div.className = "ss-item";

                    div.innerHTML = `
                        <div class="ss-tenant-name">${row.tenant}</div>
                    `;

                    grid.appendChild(div);
                });

                container.appendChild(tenantDiv);
            });
        },
    });
}

style:
/* Main container */
#system-subs-container {
    padding: 10px 4px;
}

/* Title */
.ss-title {
    font-size: 22px;
    font-weight: 600;
    margin-bottom: 14px;
    color: #1f2937;
    display: flex;
    align-items: center;
    gap: 10px;
}

.ss-title::before {
    content: "📦";
    font-size: 22px;
}

/* List root */
#system-subs-list {
    display: flex;
    flex-direction: column;
    gap: 26px;
}

/* Empty state */
.ss-empty {
    padding: 22px;
    text-align: center;
    font-size: 15px;
    color: #6b7280;
    background: #f9fafb;
    border-radius: 12px;
    border: 1px solid #e5e7eb;
}

/* Tenant block */
.ss-tenant {
    background: rgba(255, 255, 255, 0.88);
    border-radius: 18px;
    padding: 20px 24px;
    box-shadow: 0 4px 18px rgba(0, 0, 0, 0.07);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.5);
}

/* Tenant header */
.ss-tenant-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 18px;
}

.ss-tenant-title {
    font-size: 20px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 10px;
}

/* Tenant color dot */
.ss-tenant-dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: linear-gradient(135deg, #3b82f6, #60a5fa);
    box-shadow: 0 0 6px rgba(59, 130, 246, 0.6);
}

/* Subscription count */
.ss-count {
    font-size: 14px;
    color: #6b7280;
    background: #f3f4f6;
    padding: 5px 12px;
    border-radius: 10px;
    font-weight: 500;
}

/* Grid of packet cards */
.ss-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
}

/* Packet card */
.ss-item {
    background: white;
    padding: 16px 18px;
    border-radius: 16px;
    border: 1px solid #e5e7eb;
    transition: all 0.25s ease;
    box-shadow: 0 3px 10px rgba(0,0,0,0.05);
}

.ss-item:hover {
    transform: translateY(-4px);
    box-shadow: 0 6px 18px rgba(0,0,0,0.1);
}

/* Link wrapper */
.ss-link {
    text-decoration: none;
    color: inherit;
    display: block;
}

/* Packet title */
.ss-packet-title {
    font-size: 16px;
    font-weight: 600;
    color: #1f2937;
    margin-bottom: 4px;
}

/* Packet status */
.ss-packet-status {
    font-size: 13px;
    color: #6b7280;
    margin-top: 2px;
}
